    return [200, workspaceView(ws, user.id)];
  });

  route('GET', '/api/workspaces/:id/members', ({ user, params }) => {
    const { ws } = wsAccess(user, params.id);
    return [200, ws.members.map((m) => ({ ...userRef(userById(m.userId)), role: m.role }))];
