        <label>Assignee <select name="assigneeId"><option value="">Unassigned</option>${S.members.map((m) => `<option value="${esc(m.userId)}" ${m.userId === i.assigneeId ? 'selected' : ''}>${esc(m.username)}</option>`).join('')}</select></label>
