      type: f.get('type'),
      priority: f.get('priority'),
      assigneeId: f.get('assigneeId') || null,
      storyPoints: f.get('storyPoints') === '' ? null : Number(f.get('storyPoints')),
      dueDate: f.get('dueDate') || null,
